import axios from 'axios';

interface InvoiceDispatchPayload {
  recipientPhone: string;
  mediaId: string;
  invoiceNumber: string;
  customerName: string;
}

export async function sendWhatsAppInvoice({
  recipientPhone,
  mediaId,
  invoiceNumber,
  customerName
}: InvoiceDispatchPayload): Promise<boolean> {
  const accessToken = process.env.WHATSAPP_ACCESS_TOKEN;
  const phoneNumberId = process.env.WHATSAPP_PHONE_NUMBER_ID;

  const url = `https://graph.facebook.com/v19.0/${phoneNumberId}/messages`;

  try {
    const response = await axios.post(
      url,
      {
        messaging_product: 'whatsapp',
        to: recipientPhone,
        type: 'document',
        document: {
          id: mediaId,
          caption: `Hello ${customerName}, here is your official tax invoice #${invoiceNumber}. Thank you for your business!`,
          filename: `Invoice-${invoiceNumber}.pdf`
        }
      },
      {
        headers: {
          Authorization: `Bearer ${accessToken}`,
          'Content-Type': 'application/json'
        }
      }
    );

    return response.status === 200;
  } catch (error) {
    console.error('Failed to dispatch WhatsApp invoice:', error.response?.data || error.message);
    return false;
  }
}
